<script setup>
import {onMounted,ref} from 'vue';
import {usePortal} from '../auth/session.js';
const {session}=usePortal(),data=ref(null),busy=ref(false),error=ref(''),notice=ref('');
async function load(){try{data.value=(await session.api.request('/company/app-config')).data;for(const row of data.value.config.printers)row.enabled=row.enabled!==false&&row.enabled!==0;}catch(e){error.value=e.message;}}
function add(){data.value.config.printers.push({id:crypto.randomUUID(),name:'',profile:'GOOJPRT',match:'',enabled:true});}
async function save(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{data.value=(await session.api.mutate('/company/app-config','PUT',data.value)).data;notice.value='تم حفظ إعدادات تطبيق دنانير.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="card app-settings"><h2>إعدادات تطبيق دنانير</h2><p v-if="error" class="notice warn" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><form v-if="data" @submit.prevent="save"><fieldset :disabled="busy" class="formgrid"><label>اسم الشركة في التطبيق<input v-model="data.config.name" required maxlength="120"></label><label>عن شركة دنانير<textarea v-model="data.config.about" maxlength="10000" rows="3"></textarea></label><label>الشروط والأحكام<textarea v-model="data.config.terms" maxlength="20000" rows="4"></textarea></label><label>سياسة الخصوصية<textarea v-model="data.config.privacy" maxlength="20000" rows="4"></textarea></label></fieldset><h3>الطابعات المدعومة · 58 و80 ملم</h3><p class="help">الاسم للعرض، وعبارة المطابقة جزء مميز من اسم البلوتوث أو موديل الجهاز. إضافة اسم لا تضيف محرك طباعة جديدًا.</p><div v-for="(printer,index) in data.config.printers" :key="printer.id" class="app-printer-row"><label>اسم العرض<input v-model="printer.name" required maxlength="100" :disabled="busy"></label><label>المحرك<select v-model="printer.profile" :disabled="busy"><option v-for="profile in ['GOOJPRT','YHD-8006','Feasycom','Z51','sunmi','rovoo','zcs']" :key="profile" :value="profile">{{profile==='GOOJPRT'?'GOOJPRT / MTP-2':profile}}</option></select></label><label>عبارة المطابقة<input v-model="printer.match" required minlength="3" maxlength="100" :disabled="busy"></label><button type="button" class="app-printer-switch" role="switch" :aria-checked="printer.enabled" :aria-label="'تفعيل نوع الطابعة '+printer.name" :class="{on:printer.enabled}" :disabled="busy" @click="printer.enabled=!printer.enabled"><i aria-hidden="true"/><span>{{printer.enabled?'مفعّل':'معطّل'}}</span></button><button type="button" class="btn small danger" :disabled="busy" @click="data.config.printers.splice(index,1)">حذف</button></div><footer class="formfoot"><button type="button" class="btn" :disabled="busy||data.config.printers.length>=40" @click="add">إضافة طابعة</button><button class="btn primary" :disabled="busy">{{busy?'جارٍ الحفظ…':'حفظ إعدادات التطبيق'}}</button></footer></form></section></template>
<style scoped>.app-settings{margin-block:18px}.app-settings textarea{width:100%}.app-printer-row{display:flex;align-items:end;gap:10px;margin-block:12px;flex-wrap:wrap}.app-printer-row label{flex:1;min-width:160px}.app-settings fieldset{border:0;padding:0}.app-printer-switch{display:flex;align-items:center;gap:8px;border:0;background:transparent;color:var(--ink);min-height:44px;font:inherit;cursor:pointer}.app-printer-switch i{position:relative;width:42px;height:25px;background:#718096;border-radius:20px;flex:none}.app-printer-switch i:after{content:"";position:absolute;top:3px;left:3px;width:19px;height:19px;border-radius:50%;background:white}.app-printer-switch.on i{background:#087d87}.app-printer-switch.on i:after{left:20px}</style>
